import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.DfdKBe4j.js";const h=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":1788977236000}'),s={name:"reference/glossary.md"};function r(i,e,d,p,c,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p><strong>Active root</strong> : A dataset on which an effective <code>enabled=on</code> policy establishes an independently scheduled management root.</p><p><strong>Adoption</strong> : An explicit, preview-first transfer of an existing managed dataset lineage to the current installation.</p><p><strong>Dataset</strong> : An OpenZFS filesystem or volume. Boomerangz policy is attached to datasets using ZFS user properties.</p><p><strong>Destination root</strong> : The ZFS dataset beneath which received data is stored.</p><p><strong>Inactive grace period</strong> : The delay between deactivation and automatic retirement of recoverable Boomerangz state. The default is 24 hours.</p><p><strong>Lineage</strong> : The persistent identity of a managed dataset&#39;s history. It prevents a same-named replacement from being mistaken for the original data.</p><p><strong>Local destination</strong> : A destination dataset reached on the same host.</p><p><strong>Native destination</strong> : Another Boomerangz installation reached through a secured paired listener.</p><p><strong>Pairing</strong> : A credential bundle that identifies a listener, establishes server trust, and carries the authentication material and scopes granted to a client.</p><p><strong>Policy grid</strong> : The count-and-duration expression that sets snapshot cadence and retention, such as <code>24x1h,14x1d</code>.</p><p><strong>Replication</strong> : Sending a ZFS data stream to a destination dataset so it can be stored on separate storage or another host.</p><p><strong>Scheduling root</strong> : The active dataset whose policy governs a snapshot or replication job.</p><p><strong>Snapshot</strong> : A read-only ZFS point-in-time view. A snapshot on the source pool is not an independent backup.</p>',14)])])}const m=t(s,[["render",r]]);export{h as __pageData,m as default};
